  \begin{equation}\label{eq:ld-sandwich-2}
    A^x_{[\eval_y(\cdot) = (a_1,\, a_2,\, \ldots,\, a_k)]} \abc[k(\delta+\eps)^{1/2}]
    C^x_{[\eval_y(\cdot) = (a_1,\, a_2,\, \ldots,\, a_k)]}\;.
\end{equation}
\end{lemma}

